package in.asmj.ride.model;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;
@Document("ride_payments") public class PaymentRecord {
 @Id private String id; private String rideId,customerId,driverId,fleetOwnerId,method,status="PENDING",upiReference,adminNote; private UploadedAsset paymentProof; private double grossAmount,commissionRate,commissionAmount,driverNetAmount; private boolean settled; private Instant createdAt=Instant.now(),updatedAt=Instant.now(),settledAt;
 public String getId(){return id;} public String getRideId(){return rideId;} public void setRideId(String v){rideId=v;} public String getCustomerId(){return customerId;} public void setCustomerId(String v){customerId=v;} public String getDriverId(){return driverId;} public void setDriverId(String v){driverId=v;} public String getFleetOwnerId(){return fleetOwnerId;} public void setFleetOwnerId(String v){fleetOwnerId=v;} public String getMethod(){return method;} public void setMethod(String v){method=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;updatedAt=Instant.now();} public String getUpiReference(){return upiReference;} public void setUpiReference(String v){upiReference=v;} public String getAdminNote(){return adminNote;} public void setAdminNote(String v){adminNote=v;} public double getGrossAmount(){return grossAmount;} public void setGrossAmount(double v){grossAmount=v;} public double getCommissionRate(){return commissionRate;} public void setCommissionRate(double v){commissionRate=v;} public double getCommissionAmount(){return commissionAmount;} public void setCommissionAmount(double v){commissionAmount=v;} public double getDriverNetAmount(){return driverNetAmount;} public void setDriverNetAmount(double v){driverNetAmount=v;} public boolean isSettled(){return settled;} public void setSettled(boolean v){settled=v;if(v)settledAt=Instant.now();} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public Instant getSettledAt(){return settledAt;} public UploadedAsset getPaymentProof(){return paymentProof;} public void setPaymentProof(UploadedAsset v){paymentProof=v;}
}
